class Rect {
  x: int = 0;
  y: int = 0;
  width: int = 0;
  height: int = 0;
}

function overlaps(a: Rect, b: Rect): boolean {
  let horizontal: boolean = a.x < b.x + b.width && b.x < a.x + a.width;
  let vertical: boolean = a.y <= b.y + b.height;
  return horizontal && vertical;
}

export function main(): null {
  let first: Rect = { x: 2, y: 2, width: 3, height: 3 };
  let second: Rect = { x: 2, y: 2, width: 3, height: 3 };
  let collided: boolean = overlaps(first, second);
  if (collided !== true) {
    throw { code: "COLLISION_FAIL", message: "AABB result mismatch" };
  }
  console.log("collision-aabb-1:ok");
  return null;
}

